# -*- coding: utf-8 -*-
S = "полный обзор задач 9 класса (очередь G9–G11), проверено вычислением (sympy)"
P = {}
def E(t, why, **kw): P[t] = dict(src=S, why=why, **kw)
E("G9_TB_18_301", r"$x^{4}-x^{3}-51x^{2}+49x+98=(x-7)(x-2)(x+1)(x+7)$: корни из списка $2,-1,7,-7$; вопрос содержит вторую часть («какие можно исключить сразу»): по теореме о целых корнях корень делит свободный член $98$, поэтому $\pm3$ и $\pm4$ (не делители $98$) исключаются сразу; ключ отвечал только на первую часть",
  k=r"корни: $2,\ -1,\ 7,\ -7$; сразу можно исключить $\pm3$ и $\pm4$ — они не делят свободный член $98$",
  dnew={0: (r"корни: $1,\ -1,\ 2,\ -2,\ 7,\ -7$; сразу можно исключить $\pm3$ и $\pm4$", r"Ученик верно исключил числа, не делящие $98$, но остальные делители не проверил подстановкой: $1$ и $-2$ корнями не являются ($P(1)=96\ne0$, $P(-2)=-180\ne0$)."),
        1: (r"корни: $2,\ -1,\ 7,\ -7$; сразу можно исключить $1$ и $-1$", r"Ученик верно нашёл корни, но исключил $\pm1$; числа $1$ и $-1$ делят свободный член $98$, и исключить их сразу нельзя ($-1$ вообще является корнем)."),
        2: (r"корни: $2,\ 7$; сразу можно исключить все отрицательные числа", r"Ученик решил, что корни должны быть положительными, и потерял корни $-1$ и $-7$; отрицательные делители свободного члена $98$ тоже могут быть корнями.")})
